declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\Holder\UserRoleAssignmentRolesRoleAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserRoleAssignmentRolesRoleAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserRoleAssignmentRolesRoleAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRole returns null on a freshly created holder.
     */
    public function testRoleNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignmentRolesRoleAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRoleAssigned());
        $this->assertNull($holder->getRole());
    }
}
class ImplWithUserRoleAssignmentRolesRoleAttributeHolderUnitTest
{
    use UserRoleAssignmentRolesRoleAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRoleRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRole();
    }
}
